// @ts-nocheck
// ===== ทดสอบเชื่อมต่อ PLC UB-MC-CM-008 : TCP port + Modbus อ่าน HR0 (Unit 1 / 0 / 255) =====
const HOST = "192.168.3.100";
const PORTS = [502, 5000, 5001, 5002, 5007, 5100, 1025];
const TMO = 3000;
function tcp(port) {
    return new Promise(res => {
        const s = new net.Socket(), t0 = Date.now(); let done = false;
        const fin = (ok, why) => { if (done) return; done = true; try { s.destroy(); } catch (e) {} res({ port, ok, ms: Date.now() - t0, why }); };
        s.setTimeout(TMO); s.on("timeout", () => fin(false, "timeout (ไม่มีใครตอบ / firewall / คนละวง)"));
        s.on("error", e => fin(false, e.code === "ECONNREFUSED" ? "ECONNREFUSED (มีเครื่องนี้ แต่ port ปิด)" : e.code === "EHOSTUNREACH" ? "EHOSTUNREACH (หาเส้นทางไม่เจอ: กล่องไม่มี IP วง 192.168.3.x?)" : e.code || e.message));
        s.connect(port, HOST, () => fin(true, "เปิด"));
    });
}
function modbus(unit) {
    return new Promise(res => {
        const s = new net.Socket(); let buf = Buffer.alloc(0), done = false;
        const fin = r => { if (done) return; done = true; try { s.destroy(); } catch (e) {} res(Object.assign({ unit }, r)); };
        s.setTimeout(TMO); s.on("timeout", () => fin({ ok: false, why: "ต่อได้แต่ไม่ตอบคำสั่ง Modbus" }));
        s.on("error", e => fin({ ok: false, why: e.code || e.message }));
        s.on("close", () => fin({ ok: false, why: "PLC ตัดสาย (อาจจำกัด IP ที่ต่อได้ / connection เต็ม)" }));
        s.on("data", d => {
            buf = Buffer.concat([buf, d]);
            if (buf.length < 9) return;
            if (buf[7] & 0x80) return fin({ ok: false, why: "Modbus exception " + buf[8] + (buf[8] === 2 ? " (address 0 ไม่มี แต่ Modbus ทำงาน)" : buf[8] === 11 ? " (Unit ID ไม่ตรง)" : "") , modbusAlive: true });
            if (buf.length >= 9 + buf[8]) { const v = []; for (let i = 0; i < buf[8] / 2; i++) v.push(buf.readUInt16BE(9 + i * 2)); fin({ ok: true, why: "อ่าน HR0–HR9 ได้", values: v }); }
        });
        s.connect(502, HOST, () => s.write(Buffer.from([0, unit + 1, 0, 0, 0, 6, unit, 3, 0, 0, 0, 10])));
    });
}
(async () => {
    node.status({ fill: "blue", shape: "ring", text: "กำลังทดสอบ..." });
    const ports = [];
    for (const p of PORTS) ports.push(await tcp(p));
    const open = ports.filter(p => p.ok).map(p => p.port);
    let mb = [];
    if (open.includes(502)) for (const u of [1, 0, 255]) { const r = await modbus(u); mb.push(r); if (r.ok) break; }
    const ok = mb.find(r => r.ok);
    let hint;
    if (ok) hint = "✓ Modbus ใช้ได้ (Unit " + ok.unit + ") → flow สแกน Tag ควรต่อได้ ลอง Deploy flow สแกนใหม่ / กด 'หา PLC ใหม่'";
    else if (open.includes(502)) hint = mb.some(r => r.modbusAlive) ? "Modbus ทำงาน แต่ HR0 อ่านไม่ได้ → ใช้ได้ ให้ flow สแกนหาช่วงเอง" : "port 502 เปิด แต่ไม่ตอบ Modbus → เช็คใน GX Works3 ว่าเปิด MODBUS/TCP Slave และ IP ที่อนุญาต";
    else if (ports.every(p => /EHOSTUNREACH|timeout/.test(p.why))) hint = "เข้าไม่ถึงเครื่อง → ดู ping / ip addr ด้านล่าง: กล่องต้องมี IP วง 192.168.3.x ที่ eth0 และสาย LAN ต่อถึง PLC";
    else hint = "เครื่องตอบ แต่ port 502 ปิด → PLC ยังไม่เปิด Modbus TCP / ใช้ port อื่น (ดูรายการ port)";
    node.status({ fill: ok ? "green" : open.length ? "yellow" : "red", shape: "dot", text: ok ? "Modbus OK Unit " + ok.unit : open.length ? "port เปิด: " + open.join(",") : "ต่อ " + HOST + " ไม่ได้" });
    node.send({ topic: "ทดสอบ " + HOST, payload: { hint, ports: ports.map(p => p.port + ": " + p.why + " (" + p.ms + " ms)"), modbus: mb } });
})();
return null;

// @ts-nocheck
// ===== port 502 เปิดแต่ไม่ตอบ Modbus → ลองทุกแบบบน port 502 แล้วดู byte ที่ PLC ตอบกลับ =====
//   Modbus FC3/FC4/FC1 (Unit 1, 0, 255) · SLMP/MC 3E Binary · 3E ASCII · 4E Binary · รอ banner
const HOST = "192.168.3.100", PORT = +(msg.port || 502), TMO = 3000;
function hex(b) { return b.slice(0, 40).toString("hex").replace(/(..)/g, "$1 ").trim(); }
function tryFrame(name, frame) {
    return new Promise(res => {
        const s = new net.Socket(); let buf = Buffer.alloc(0), done = false, t0 = Date.now();
        const fin = why => { if (done) return; done = true; try { s.destroy(); } catch (e) {} res({ name, ok: buf.length > 0, why, bytes: buf.length, hex: buf.length ? hex(buf) : "", ascii: buf.length ? buf.toString("latin1").replace(/[^\x20-\x7e]/g, ".").slice(0, 40) : "", ms: Date.now() - t0 }); };
        s.setTimeout(TMO); s.on("timeout", () => fin(buf.length ? "ตอบแล้ว" : "ไม่ตอบใน " + TMO / 1000 + " วิ"));
        s.on("error", e => fin(e.code || e.message));
        s.on("close", () => fin(buf.length ? "ตอบแล้ว PLC ปิดสาย" : "PLC ตัดสายทันที (ไม่รับคำสั่งแบบนี้ / IP ไม่ได้รับอนุญาต)"));
        s.on("data", d => { buf = Buffer.concat([buf, d]); setTimeout(() => fin("ตอบแล้ว"), 150); });
        s.connect(PORT, HOST, () => { if (frame) s.write(frame); });
    });
}
function tryUdp(name, port, frame) {   // SLMP แบบ UDP (เครื่องนี้ตั้ง SLMP UDP 8001 / 8002)
    return new Promise(res => {
        const u = dgram.createSocket("udp4"), t0 = Date.now(); let done = false;
        const fin = (b, why) => { if (done) return; done = true; try { u.close(); } catch (e) {} res({ name, ok: !!b, why, bytes: b ? b.length : 0, hex: b ? hex(b) : "", ascii: "", ms: Date.now() - t0 }); };
        u.on("message", b => fin(b, b.readUInt16LE(0) === 0xD0 && b.readUInt16LE(9) === 0 ? "ตอบแล้ว · อ่าน D0 ได้ ✓" : "ตอบแล้ว (end code 0x" + (b.length > 10 ? b.readUInt16LE(9).toString(16) : "?") + ")"));
        u.on("error", e => fin(null, e.code || e.message));
        setTimeout(() => fin(null, "ไม่ตอบใน " + TMO / 1000 + " วิ (UDP)"), TMO);
        u.send(frame, port, HOST);
    });
}
const mb = (u, fc, a, q) => Buffer.from([0, 1, 0, 0, 0, 6, u, fc, a >> 8, a & 255, q >> 8, q & 255]);
function mc3e() { const b = Buffer.alloc(21); b.writeUInt16LE(0x50, 0); b[3] = 0xFF; b.writeUInt16LE(0x3FF, 4); b.writeUInt16LE(12, 7); b.writeUInt16LE(0x10, 9); b.writeUInt16LE(0x0401, 11); b.writeUIntLE(0, 15, 3); b[18] = 0xA8; b.writeUInt16LE(10, 19); return b; }
function mc4e() { const b = Buffer.alloc(25); b.writeUInt16LE(0x54, 0); b.writeUInt16LE(1, 2); b[7] = 0xFF; b.writeUInt16LE(0x3FF, 8); b.writeUInt16LE(12, 11); b.writeUInt16LE(0x10, 13); b.writeUInt16LE(0x0401, 15); b.writeUIntLE(0, 19, 3); b[22] = 0xA8; b.writeUInt16LE(10, 23); return b; }
const TESTS = [
    ["รอ banner (ไม่ส่งอะไร)", null],
    ["Modbus FC3 HR0 Unit 1", mb(1, 3, 0, 10)], ["Modbus FC3 HR0 Unit 0", mb(0, 3, 0, 10)], ["Modbus FC3 HR0 Unit 255", mb(255, 3, 0, 10)],
    ["Modbus FC4 IR0 Unit 1", mb(1, 4, 0, 10)], ["Modbus FC1 Coil0 Unit 1", mb(1, 1, 0, 16)], ["Modbus FC3 HR0 Unit 2", mb(2, 3, 0, 10)],
    ["SLMP/MC 3E Binary D0", mc3e()], ["SLMP/MC 3E ASCII D0", Buffer.from("500000FF03FF000018001004010000D*000000000A", "latin1")], ["SLMP/MC 4E Binary D0", mc4e()]
];
(async () => {
    const out = [];
    for (const [n, f] of TESTS) { node.status({ fill: "blue", shape: "ring", text: "ลอง " + n }); out.push(await tryFrame(n, f)); await new Promise(r => setTimeout(r, 300)); }
    for (const port of [8001, 8002]) { node.status({ fill: "blue", shape: "ring", text: "ลอง SLMP UDP " + port }); out.push(await tryUdp("SLMP 3E Binary UDP " + port + " D0", port, mc3e())); }
    const hit = out.filter(r => r.ok && r.name !== "รอ banner (ไม่ส่งอะไร)");
    const banner = out[0].ok;
    let hint = hit.length ? "✓ ตอบกลับ: " + hit.map(r => r.name).join(", ") + " → ส่งรูปนี้มา จะตั้ง flow สแกนให้ตรงแบบนั้น"
        : banner ? "PLC ส่งข้อความเองตอนต่อ (banner) → ไม่ใช่ Modbus/SLMP อาจเป็นอุปกรณ์อื่น ดู ascii"
        : out.filter(r => !/UDP/.test(r.name)).every(r => /ตัดสาย/.test(r.why)) ? "ตัดสายทุกแบบ → PLC จำกัด IP ที่ต่อได้ (ใส่ IP กล่องใน GX Works3) หรือ connection เต็ม (มีเครื่องอื่นต่อค้างอยู่)"
        : "ต่อได้แต่ไม่ตอบทุกแบบ → port 502 อาจเป็นของอุปกรณ์อื่น (HMI / Gateway) หรือ PLC ยังไม่ได้เขียน parameter MODBUS/TCP ลงเครื่อง (ต้อง Write + Reset PLC)";
    node.status({ fill: hit.length ? "green" : "red", shape: "dot", text: hit.length ? "ตอบ: " + hit[0].name : "ไม่ตอบทุกแบบ" });
    node.send({ topic: "ทดสอบทุกแบบ " + HOST + ":" + PORT, payload: { hint, tests: out } });
})();
return null;
